    'The app-relative path to give MCP clients that sign in with OAuth. It always requires an access token, so clients can discover how to sign in.' => 'Шлях відносно застосунку, який треба надати MCP-клієнтам, що входять через OAuth. Він завжди вимагає токен доступу, щоб клієнти могли дізнатися, як увійти.',
