    'The template receives `element` and `static` variables. Its output is sanitized and displayed as non-interactive content; form controls, scripts, and registered assets are not supported.' => 'Шаблон отримує змінні `element` і `static`. Його вивід очищується й відображається як неінтерактивний вміст; елементи керування форм, скрипти та зареєстровані ресурси не підтримуються.',
    'The template will be rendered with an `element` variable.' => 'Шаблон оброблятиметься зі змінною `element`.',
