    'Whether authors should be able to choose which time zone the time is in.' => 'Чи надаватиметься авторам можливість вибору часового поясу, в якому вказується час.',
    'Whether authors should be able to upload files directly to the field, rather than requiring them to select/upload assets via the selection modal.' => 'Визначає, чи дозволено авторам завантажувати файли безпосередньо в поле замість вибору або завантаження ресурсів через модальне вікно вибору.',
    'Whether buttons should only show their icons, hiding their text labels.' => 'Чи показувати на кнопках лише значки, без текстових міток.',
    'Whether card views which include this field should show the custom ON/OFF labels, rather than the field name.' => 'Визначає, чи картки, що містять це поле, мають відображати користувацькі мітки УВІМК./ВИМК. замість назви поля.',
