    'Whether the field should only render inline Markdown, without wrapping paragraphs.' => 'Визначає, чи має поле відображати лише рядкову розмітку Markdown без обгортання в абзаци.',
    'Whether the number of elements in this source should be shown beside it in the navigation.' => 'Визначає, чи показувати кількість елементів у цьому джерелі поруч із ним у навігації.',
    'Whether the site menu should be shown for {type} selection modals.' => 'Визначає, чи показуватиметься меню сайту для модальних вікон вибору об\'єкта ({type}).',
    'Whether the structure of the related {type} should be maintained.' => 'Чи слід зберігати структуру зв\'язаного типу {type}.',
